#include <iostream>
using namespace std;

int main() {
    int n;
    cin >> n;

    while (n--) {
        int value;
        cin >> value;

        int x = 0, p = 1, digit = 1;
        int repetitions = 0, position = 0;

        while (x != value) {
            x += digit * p;
            p *= 10;
            ++repetitions;
            ++position;

            if (repetitions == 4) {
                ++digit;
                repetitions = 0;
                x = 0;
                p = 1;
            }
        }

        cout << position << '\n';
    }

    return 0;
}

#include <iostream>
#include <vector>
using namespace std;

int main() {
    int n;
    cin >> n;

    vector<long long> v(n);
    long long x = 0, p = 1, j = 1, nr = 0, nr1 = 0;

    for (int i = 0; i < n; ++i) {
        cin >> v[i];

        while (x < v[i]) {
            x = x * p + j;
            p *= 10;
            ++nr;
            ++nr1;

            if (nr == 4) {
                ++j;
                nr = 0;
            }
        }

        cout << nr1 << '\n';
    }

    return 0;
}

