    while (n--) {
        int target, count = 0;
        cin >> target;

        for (int digit = 1; digit <= 9; ++digit) {
            int value = 0;
            for (int length = 1; length <= 4; ++length) {
                value = value * 10 + digit;
                ++count;

                if (value == target) {
                    cout << count << '\n';
                    goto found;
                }
            }
        }

    found:;
