}

#include <iostream>
#include <string>
using namespace std;

int main() {
    int n;
    cin >> n;

    while (n--) {
        string x;
        cin >> x;
        int digit = x[0] - '0';
        int length = static_cast<int>(x.size());
        cout << (digit - 1) * 10 + length * (length + 1) / 2 << '\n';
    }

    return 0;
}

